using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using System;
using System.IO;
using System.Linq;
using System.Text;
using ConRoi.Investigation.V36;
using Object = UnityEngine.Object;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            if (EditorApplication.isPlaying || EditorApplication.isCompiling)
                throw new Exception("Edit compiled only");
            var s = Object.FindFirstObjectByType<InvestigationSession>();
            var sc = s.gameObject.scene;
            if (!sc.path.EndsWith("r102.unity"))
                throw new Exception("r102 only");
            var script = AssetDatabase.LoadAssetAtPath<MonoScript>("Assets/Scripts/InvestigationV36/InvestigationInteractable.cs");
            if (!script || script.GetClass() != typeof(InvestigationInteractable))
                throw new Exception("Persistent MonoScript required");
            var w = s.transform.Find("Workshop_GDD36");
            var names = new[]{"Self_return_gate_L_C_D/L_return_leaf|mechanism|inspect|Khám", "Self_return_gate_L_C_D/C_latch|mechanism|inspect|Khám", "DK_release_handle|mechanism|rope|Giữ / thả D", "M_hook_dust|hook|inspect|Khám", "R03_Investigation|r03|inspect|Xem", "R12_Investigation|r12|inspect|Xem", "Khai_Investigation|khai|inspect|Nói chuyện với", "Evidence_henri|henri|inspect|Xem", "Evidence_coat|coat|inspect|Xem", "Evidence_shoe|shoe|inspect|Xem", "Evidence_fabric|fabric|inspect|Xem", "Evidence_phone|phone|inspect|Xem", "Evidence_slide|slide|inspect|Xem", "Evidence_shoeprint|shoeprint|inspect|Xem", "Reconstruction_table_controls||table|Dựng lại", "StagedRope_R03|r03|inspect|Khám dây dàn dựng", "@Ha_Investigation|ha|inspect|Hỏi"};
            var log = new StringBuilder("Persistent MonoScript=" + AssetDatabase.AssetPathToGUID(AssetDatabase.GetAssetPath(script)) + "\n");
            foreach (var entry in names)
            {
                var a = entry.Split('|');
                var t = a[0].StartsWith("@") ? s.transform.Find(a[0].Substring(1)) : w.Find(a[0]);
                if (!t)
                    throw new Exception("Missing " + a[0]);
                GameObjectUtility.RemoveMonoBehavioursWithMissingScript(t.gameObject);
                foreach (var old in t.GetComponents<InvestigationInteractable>())
                    Object.DestroyImmediate(old);
                var i = t.gameObject.AddComponent<InvestigationInteractable>();
                i.evidenceId = a[1];
                i.action = a[2];
                i.verb = a[3];
                var c = t.GetComponent<BoxCollider>();
                if (c)
                {
                    var bounds = new Bounds();
                    bool first = true;
                    foreach (var rr in t.GetComponentsInChildren<Renderer>(true))
                    {
                        if (rr is LineRenderer)
                            continue;
                        var b = rr.bounds;
                        for (int k = 0; k < 8; k++)
                        {
                            var p = b.center + Vector3.Scale(b.extents, new Vector3((k & 1) == 0 ? -1 : 1, (k & 2) == 0 ? -1 : 1, (k & 4) == 0 ? -1 : 1));
                            p = t.InverseTransformPoint(p);
                            if (first)
                            {
                                bounds = new Bounds(p, Vector3.zero);
                                first = false;
                            }
                            else
                                bounds.Encapsulate(p);
                        }
                    }

                    if (!first)
                    {
                        c.center = bounds.center;
                        c.size = new Vector3(Mathf.Max(.06f, bounds.size.x), Mathf.Max(.04f, bounds.size.y), Mathf.Max(.06f, bounds.size.z));
                    }

                    log.AppendLine(t.name + " collider=" + c.bounds);
                }
            }

            EditorSceneManager.MarkSceneDirty(sc);
            EditorSceneManager.SaveScene(sc);
            sc = EditorSceneManager.OpenScene(sc.path);
            var all = sc.GetRootGameObjects().SelectMany(g => g.GetComponentsInChildren<Transform>(true)).ToArray();
            int missing = all.Sum(t => GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject));
            int count = Object.FindObjectsByType<InvestigationInteractable>(FindObjectsSortMode.None).Length;
            log.AppendLine("REOPEN missing=" + missing + " interactions=" + count);
            File.WriteAllText("Test/KetQua/investigation_r102/interaction-persistence-fix.txt", log.ToString());
            if (missing != 0 || count != 17)
                throw new Exception(log.ToString());
            r.Log(log.ToString());
        }
    }
}

